    const dateBtn=(k,v)=>{const d=v?new Date(v+'T00:00:00'):null;const t=d&&!isNaN(d)?(['from','to'].includes(k)?niceDate(v):d.toLocaleDateString('en-IN',{weekday:'short',day:'2-digit',month:'short',year:'numeric'})):'Select date';return `<span class="ds-date-field ds-calbtn-wrap"><button type="button" class="ds-calbtn" data-ds-cal="${k}" aria-label="Choose date" aria-haspopup="dialog"><span class="ds-calbtn-ic">${svg('calendar',15)}</span><span>${E(t)}</span>${svg('chevDown',13)}</button><input type="hidden" data-ds-change="${k}" value="${E(v||'')}"></span>`};
    const nav = () => `<div class="ds-subnav">${[['report','Daily report','clipboard'],['ratings','Ratings','star']].map(([k,name,ico])=>`<button class="ds-subnav-btn ${state.page===k?'on':''}" data-ds-action="page:${k}"><span class="ds-subnav-icon">${svg(ico,22)}</span>${name}</button>`).join('')}</div>`;
